import type { PermissionGrant } from './account_actor.js'
import { actingAsFields } from '../lib/acting-as.js'

// Per design/stories/tower/007-invites-and-invite-codes.md and ADR
// 0021/0067/0082/0053. `identifiedBy: 'token'` -- a single-use,
// non-guessable invite token, generated by `routes/invites.ts` for a
// general-purpose invite, or deterministically by `routes/provisioning.ts`
// for the one bootstrap case that needs retry-idempotency.
//
// `application: null` means tenant-wide (lands the invitee on `_admin` via
// normal login) -- the shape ADR 0067's first-admin invite always uses;
// `routes/invites.ts`'s general-purpose route also accepts a specific
// application slug.
export interface InviteState {
  tenant: string
  application: string | null
  contactId: string
  roles: Array<{ name: string, scope: 'tenant' | { application: string } }>
  permissions: PermissionGrant[]
  status: 'pending' | 'accepted' | 'revoked' | 'expired'
  createdAt: string
  expiresAt: string | null
}

interface CreateCommand {
  tenant: string
  application: string | null
  contactId: string
  roles: InviteState['roles']
  permissions: PermissionGrant[]
  expiresAt: string | null
  actingAs?: string
}

interface AcceptCommand {
  accountId: string
}

interface RevokeCommand {
  actingAs?: string
}

function create(_invite: InviteState, command: CreateCommand) {
  return {
    type: 'invite.created',
    tenant: command.tenant,
    application: command.application,
    contactId: command.contactId,
    roles: command.roles ?? [],
    permissions: command.permissions ?? [],
    expiresAt: command.expiresAt,
    ...actingAsFields(command),
  }
}

function isRedeemable(invite: InviteState) {
  if (invite.status !== 'pending') return false
  if (invite.expiresAt && new Date(invite.expiresAt).getTime() < Date.now()) return false
  return true
}

function accept(_invite: InviteState, command: AcceptCommand) {
  return { type: 'invite.accepted', accountId: command.accountId }
}

function rejectAccept() {
  return Promise.reject(new Error('invite is not pending or has expired'))
}

// `DELETE /tenants/{tenantSlug}/invites/{token}` is a soft alias for this
// (ADR 0053) -- the route itself treats an already-revoked invite as a
// no-op success, matching `applications.ts`'s own DELETE convention, so
// this guard only ever fires for a genuine direct double-revoke.
function isPending(invite: InviteState) {
  return invite.status === 'pending'
}

function revoke(_invite: InviteState, command: RevokeCommand) {
  return { type: 'invite.revoked', ...actingAsFields(command) }
}

function rejectRevoke() {
  return Promise.reject(new Error('invite is not pending'))
}

function created(invite: InviteState, event: CreateCommand) {
  invite.tenant = event.tenant
  invite.application = event.application
  invite.contactId = event.contactId
  invite.roles = event.roles ?? []
  invite.permissions = event.permissions ?? []
  invite.status = 'pending'
  invite.createdAt = new Date(0).toISOString() // replaced by consequent's own event timestamp on read
  invite.expiresAt = event.expiresAt
}

function accepted(invite: InviteState) {
  invite.status = 'accepted'
}

function revoked(invite: InviteState) {
  invite.status = 'revoked'
}

export default function inviteActor() {
  return {
    actor: {
      namespace: 'tower',
      type: 'invite',
      identifiedBy: 'token',
      searchableBy: ['tenant', 'contactId', 'status'],
    },
    state: {
      tenant: '',
      application: null,
      contactId: '',
      roles: [],
      permissions: [],
      status: 'pending',
      createdAt: '',
      expiresAt: null,
    },
    commands: {
      create,
      accept: [
        { when: isRedeemable, then: accept },
        rejectAccept,
      ],
      revoke: [
        { when: isPending, then: revoke },
        rejectRevoke,
      ],
    },
    events: {
      created,
      accepted,
      revoked,
    },
  }
}
